1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		return created, err
179	}
180	
181	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
182	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
183		note = clean(note)
184		if err := requireNonEmpty("重叠说明", note); err != nil {
185			return OverlapNote{}, err
186		}
187		if clean(shiftA) == clean(shiftB) {
188			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
189		}
190	
191		var saved OverlapNote
192		err := svc.store.mutate(func(d *Data) error {
193			sa, _ := findShift(d, clean(shiftA))
194			sb, _ := findShift(d, clean(shiftB))
195			if sa == nil || sb == nil {
196				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
197			}
198			if sa.Position != sb.Position {
199				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
200					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
201			}
202			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
203				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
204					ErrInvalidInput, sa.ID, sb.ID)
205			}
206			d.NoteSeq++
207			x, y := notePair(sa.ID, sb.ID)
208			saved = OverlapNote{
209				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
210				Position:  sa.Position,
211				ShiftA:    x,
212				ShiftB:    y,
213				Note:      note,
214				CreatedAt: svc.now(),
215			}
216			d.Notes = append(d.Notes, saved)
217			return nil
218		})
219		return saved, err
220	}
221	
222	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
223	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
224		shiftID = clean(shiftID)
225		content = clean(content)
226		constraints = clean(constraints)
227		followOwner = clean(followOwner)
228		if err := requireNonEmpty("事项内容", content); err != nil {
229			return Item{}, err
230		}
231		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
232			return Item{}, err
233		}
234		if !severity.valid() {
235			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
236		}
237	
238		var created Item
239		err := svc.store.mutate(func(d *Data) error {
240			sh, _ := findShift(d, shiftID)
241			if sh == nil {
242				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
243			}
244			if sh.Closed {
245				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
246			}
247			d.ItemSeq++
248			now := svc.now()
249			created = Item{
250				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
251				OriginShiftID:  sh.ID,
252				ShiftIDs:       []string{sh.ID},
253				CurrentShiftID: sh.ID,
254				Content:        content,
255				Severity:       severity,
256				Constraints:    constraints,
257				FollowOwner:    followOwner,
258				CreatedAt:      now,
259				Events: []ItemEvent{
260					{At: now, Kind: "created", Detail: "事项建立"},
261				},
262			}
263			d.Items = append(d.Items, created)
264			return nil
265		})
266		return created, err
267	}
268	
269	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
270	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
271		itemID = clean(itemID)
272		content = clean(content)
273		constraints = clean(constraints)
274		followOwner = clean(followOwner)
275		if err := requireNonEmpty("事项内容", content); err != nil {
276			return Item{}, err
277		}
278		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
279			return Item{}, err
280		}
281		if !severity.valid() {
282			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
283		}
284	
285		var updated Item
286		err := svc.store.mutate(func(d *Data) error {
287			it, _ := findItem(d, itemID)
288			if it == nil {
289				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
290			}
291			sh, _ := findShift(d, it.CurrentShiftID)
292			if sh == nil || sh.Closed {
293				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
294					ErrShiftClosed, itemID, it.CurrentShiftID)
295			}
296			changes := []string{}
297			if it.Content != content {
298				changes = append(changes, "内容")
299			}
300			if it.Severity != severity {
301				changes = append(changes, "严重程度")
302			}
303			if it.Constraints != constraints {
304				changes = append(changes, "限制条件")
305			}
306			if it.FollowOwner != followOwner {
307				changes = append(changes, "后续负责人")
308			}
309			it.Content = content
310			it.Severity = severity
311			it.Constraints = constraints
312			it.FollowOwner = followOwner
313			it.Events = append(it.Events, ItemEvent{
314				At:     svc.now(),
315				Kind:   "updated",
316				Detail: "修改字段：" + joinOr(changes, "无变更"),
317			})
318			updated = *it
319			return nil
320		})
321		return updated, err
322	}
323	
324	func joinOr(xs []string, or string) string {
325		if len(xs) == 0 {
326			return or
327		}
328		return strings.Join(xs, "、")
329	}
330	
331	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
332	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
333		itemID = clean(itemID)
334		operator = clean(operator)
335		if err := requireNonEmpty("操作人", operator); err != nil {
336			return Item{}, err
337		}
338	
339		var closed Item
340		err := svc.store.mutate(func(d *Data) error {
341			it, _ := findItem(d, itemID)
342			if it == nil {
343				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
344			}
345			if it.Closed {
346				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
347			}
348			sh, _ := findShift(d, it.CurrentShiftID)
349			if sh == nil || sh.Closed {
350				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
351					ErrShiftClosed, itemID, it.CurrentShiftID)
352			}
353			now := svc.now()
354			it.Closed = true
355			it.ClosedAt = &now
356			it.CloseOperator = operator
357			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
358			closed = *it
359			return nil
360		})
361		return closed, err
362	}
363	
364	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
365	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
366	// 交接视为已完成，可以结束。
367	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
368	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
369	// 事项归属与已保存的处理经过。
370	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
371		shiftID = clean(shiftID)
372		var result Shift
373		err := svc.store.mutate(func(d *Data) error {
374			sh, _ := findShift(d, shiftID)
375			if sh == nil {
376				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
377			}
378			if sh.Closed {
379				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
380			}
381			for i := range d.Handovers {
382				h := &d.Handovers[i]
383				if h.ToShiftID == sh.ID && !h.Completed() {
384					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
385						ErrHandoverState, h.ID)
386				}
387			}
388			now := svc.now()
389			sh.Closed = true
390			sh.ClosedAt = &now
391	
392			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
393			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
394			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
395			for i := range d.Items {
396				it := &d.Items[i]
397				if it.CurrentShiftID != sh.ID {
398					continue
399				}
400				record.Items = append(record.Items, CloseItemSnapshot{
401					ItemID:        it.ID,
402					Content:       it.Content,
403					Severity:      it.Severity,
404					Constraints:   it.Constraints,
405					FollowOwner:   it.FollowOwner,
406					Closed:        it.Closed,
407					ClosedAt:      it.ClosedAt,
408					CloseOperator: it.CloseOperator,
409				})
410			}
411			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
412			sh.CloseRecord = record
413	
414			result = *sh
415			return nil
416		})
417		return result, err
418	}
419	
420	// CreateHandover 由交班班次向同岗位接班班次发起交接。
421	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
422	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
423	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
424	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
425	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
426	// 要求仅对首次发起生效。
427	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
428		fromShiftID = clean(fromShiftID)
429		toShiftID = clean(toShiftID)
430	
431		var result Handover
432		err := svc.store.mutate(func(d *Data) error {
433			from, _ := findShift(d, fromShiftID)
434			to, _ := findShift(d, toShiftID)
435			if from == nil {
436				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
437			}
438			if to == nil {
439				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
440			}
441			if from.ID == to.ID {
442				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
443			}
444			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
445			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
446			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
447			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
448			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
449			// 存在与交给自身的校验仍在其前。
450			for i := range d.Handovers {
451				if d.Handovers[i].FromShiftID == from.ID {
452					existing := &d.Handovers[i]
453					result = *existing
454					if existing.ToShiftID != to.ID {
455						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
456							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
457					}
458					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
459				}
460			}
461	
462			if from.Position != to.Position {
463				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
464					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
465			}
466	
467			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
468			// 交班班次已经结束，重叠区间须有说明。
469			if to.Closed {
470				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
471			}
472			if to.Start.Before(from.Start) {
473				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
474					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
475					from.ID, from.Start.Format(time.RFC3339))
476			}
477			if !from.Closed {
478				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
479					ErrShiftNotClosed, from.ID)
480			}
481			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
482				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
483					ErrOverlap, from.ID, to.ID)
484			}
485	
486			entries := []HandoverEntry{}
487			for i := range d.Items {
488				it := &d.Items[i]
489				if it.CurrentShiftID == from.ID && !it.Closed {
490					entries = append(entries, HandoverEntry{
491						ItemID:      it.ID,
492						Content:     it.Content,
493						Severity:    it.Severity,
494						Constraints: it.Constraints,
495						FollowOwner: it.FollowOwner,
496						Status:      EntryPending,
497					})
498				}
499			}
500			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
501	
502			d.HandoverSeq++
503			now := svc.now()
504			h := Handover{
505				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
506				Position:    from.Position,
507				FromShiftID: from.ID,
508				ToShiftID:   to.ID,
509				CreatedAt:   now,
510				Entries:     entries,
511			}
512			if len(entries) == 0 {
513				// 空清单直接完成。
514				h.CompletedAt = &now
515			}
516			d.Handovers = append(d.Handovers, h)
517			result = h
518			return nil
519		})
520		return result, err
521	}
522	
523	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
524	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
525	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
526	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
527	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
528	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
529	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
530	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
531		handoverID = clean(handoverID)
532		itemID = clean(itemID)
533		operator = clean(operator)
534		reason = clean(reason)
535		trackingNote = clean(trackingNote)
536		nextFollowOwner = clean(nextFollowOwner)
537	
538		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
539			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
540		}
541		if err := requireNonEmpty("操作人", operator); err != nil {
542			return Handover{}, err
543		}
544	
545		var result Handover
546		err := svc.store.mutate(func(d *Data) error {
547			h, _ := findHandover(d, handoverID)
548			if h == nil {
549				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
550			}
551			e, _ := findEntry(h, itemID)
552			if e == nil {
553				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
554			}
555			if e.Status.Received() {
556				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
557					ErrHandoverState, e.ItemID, e.Status.Label())
558			}
559			if e.Status == EntryReturned {
560				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
561				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
562				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
563				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
564					ErrHandoverState, e.ItemID, h.ID)
565			}
566			switch action {
567			case ActionReturn:
568				if err := requireNonEmpty("退回原因", reason); err != nil {
569					return err
570				}
571			case ActionTrack:
572				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
573					return err
574				}
575				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
576					return err
577				}
578			}
579	
580			now := svc.now()
581			switch action {
582			case ActionConfirm:
583				e.Status = EntryConfirmed
584			case ActionTrack:
585				e.Status = EntryTracking
586				e.TrackingNote = trackingNote
587				e.FollowOwner = nextFollowOwner
588			case ActionReturn:
589				e.Status = EntryReturned
590				e.Rounds = append(e.Rounds, ReturnRound{
591					Seq:            len(e.Rounds) + 1,
592					ReturnedAt:     now,
593					ReturnOperator: operator,
594					Reason:         reason,
595				})
596			}
597			e.Operator = operator
598			e.ProcessedAt = &now
599	
600			if action != ActionReturn {
601				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
602				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
603					it.CurrentShiftID = h.ToShiftID
604					if !contains(it.ShiftIDs, h.ToShiftID) {
605						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
606					}
607					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
608					if action == ActionTrack {
609						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
610						it.FollowOwner = nextFollowOwner
611						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
612					}
613					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
614				}
615			}
616	
617			if h.Completed() {
618				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
619				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
620				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
621				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
622				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
623				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
624				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
625				// 项无法再处理，完成时间不会被改写。
626				h.CompletedAt = &now
627			}
628			result = *h
629			return nil
630		})
631		return result, err
632	}
633	
634	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
635	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
636	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
637	
638	func contains(xs []string, x string) bool {
639		for _, v := range xs {
640			if v == x {
641				return true
642			}
643		}
644		return false
645	}
646	
647	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
648	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
649	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
650	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
651	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
652	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
653	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
654		handoverID = clean(handoverID)
655		itemID = clean(itemID)
656		operator = clean(operator)
657		supplement = clean(supplement)
658		if err := requireNonEmpty("操作人", operator); err != nil {
659			return Handover{}, err
660		}
661		if err := requireNonEmpty("补充说明", supplement); err != nil {
662			return Handover{}, err
663		}
664	
665		var result Handover
666		err := svc.store.mutate(func(d *Data) error {
667			h, _ := findHandover(d, handoverID)
668			if h == nil {
669				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
670			}
671			e, _ := findEntry(h, itemID)
672			if e == nil {
673				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
674			}
675			if e.Status != EntryReturned {
676				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
677					ErrHandoverState, e.ItemID, e.Status.Label())
678			}
679			if len(e.Rounds) == 0 {
680				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
681			}
682			round := &e.Rounds[len(e.Rounds)-1]
683			if round.ResubmittedAt != nil {
684				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
685			}
686			now := svc.now()
687			round.Supplement = supplement
688			round.SupplementOperator = operator
689			round.SupplementAt = &now
690			round.ResubmittedAt = &now
691			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
692			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
693			e.Status = EntryPending
694			e.Operator = ""
695			e.ProcessedAt = nil
696			result = *h
697			return nil
698		})
699		return result, err
700	}
