718	// GetItem 按稳定编号查询事项。
719	func (svc *Service) GetItem(id string) (Item, error) {
720		it, _ := findItem(&svc.store.data, clean(id))
721		if it == nil {
722			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
723		}
724		return *it, nil
725	}
726	
727	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
728	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
729	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
730	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
731	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
732	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
733	// 不改变事项、交接进度或班次结束时记录。
734	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
735		itemID = clean(itemID)
736		d := &svc.store.data
737		it, _ := findItem(d, itemID)
738		if it == nil {
739			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
740		}
741		j := ItemJourney{Item: *it}
742	
743		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
744		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
745		// 该轮重新提交、后续处理）。
746		type keyedEvent struct {
747			ev    JourneyEvent
748			group string // "" 表示事项自身事件，否则为交接编号
749			ord   int    // 同一（时刻、分组）内的先后
750		}
751		var events []keyedEvent
752		seq := 0
753		add := func(ev JourneyEvent, group string) {
754			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
755			seq++
756		}
757	
758		// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
759		// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
760		receivedUsed := make([]bool, len(it.Events))
761	
762		hs := append([]Handover(nil), d.Handovers...)
763		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
764		for k := range hs {
765			h := &hs[k]
766			e, _ := findEntry(h, itemID)
767			if e == nil {
768				continue
769			}
770			j.HasHandovers = true
771			j.Results = append(j.Results, EntryView{
772				HandoverID: h.ID,
773				FromShift:  h.FromShiftID,
774				ToShift:    h.ToShiftID,
775				Entry:      *e,
776			})
777	
778			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
779			add(JourneyEvent{
780				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
781				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
782			}, h.ID)
783			for _, r := range e.Rounds {
784				add(JourneyEvent{
785					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
786					Kind: "return", Operator: r.ReturnOperator,
787					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
788					RoundSeq: r.Seq, Reason: r.Reason,
789				}, h.ID)
790				if r.ResubmittedAt != nil {
791					add(JourneyEvent{
792						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
793						Kind: "resubmit", Operator: r.SupplementOperator,
794						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
795						RoundSeq: r.Seq, Supplement: r.Supplement,
796						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
797					}, h.ID)
798				}
799			}
800			if e.Status.Received() {
801				kind := "confirm"
802				if e.Status == EntryTracking {
803					kind = "track"
804				}
805				ev := JourneyEvent{
806					Kind: kind, Operator: e.Operator,
807					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
808					TrackingNote: e.TrackingNote,
809					// 继续跟踪当时指定的后续负责人取自交接记录快照，
810					// 之后修改事项负责人不改变这里的历史值。
811					FollowOwner: e.FollowOwner,
812				}
813				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
814				// 时间标为未记录，排在有真实时间的事件之后。
815				if validProcessedAt(e.ProcessedAt) {
816					ev.At, ev.TimeKnown = *e.ProcessedAt, true
817				}
818				add(ev, h.ID)
819				if validProcessedAt(e.ProcessedAt) {
820					for i := range it.Events {
821						iev := &it.Events[i]
822						if iev.Kind == "received" && !receivedUsed[i] &&
823							iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
824							receivedUsed[i] = true
825							break
826						}
827					}
828				}
829			}
830		}
831	
832		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
833		// received 事件（旧数据）也保留。
834		for i, iev := range it.Events {
835			if iev.Kind == "received" && receivedUsed[i] {
836				continue
837			}
838			add(JourneyEvent{
839				At: iev.At, TimeKnown: !iev.At.IsZero(),
840				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
841			}, "")
842		}
843	
844		sort.SliceStable(events, func(i, k int) bool {
845			a, b := events[i], events[k]
846			if a.ev.TimeKnown != b.ev.TimeKnown {
847				return a.ev.TimeKnown
848			}
849			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
850				return a.ev.At.Before(b.ev.At)
851			}
852			if a.group != b.group {
853				return a.group < b.group
854			}
855			return a.ord < b.ord
856		})
857		for _, ke := range events {
858			j.Events = append(j.Events, ke.ev)
859		}
860		return j, nil
861	}
862	
863	// GetHandover 按编号查询交接。
864	func (svc *Service) GetHandover(id string) (Handover, error) {
865		h, _ := findHandover(&svc.store.data, clean(id))
866		if h == nil {
867			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
868		}
869		return *h, nil
870	}
871	
872	// ListHandovers 返回全部交接记录，按编号排序。
873	func (svc *Service) ListHandovers() []Handover {
874		out := append([]Handover(nil), svc.store.data.Handovers...)
875		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
876		return out
877	}
878	
879	// OverlapNotes 返回涉及指定班次的全部重叠说明。
880	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
881		shiftID = clean(shiftID)
882		out := []OverlapNote{}
883		for _, n := range svc.store.data.Notes {
884			if n.ShiftA == shiftID || n.ShiftB == shiftID {
885				out = append(out, n)
886			}
887		}
888		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
889		return out
890	}
891	
892	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
893	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
894	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
895	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
896		shiftID = clean(shiftID)
897		d := &svc.store.data
898		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
899		sh, _ := findShift(d, shiftID)
900		if sh == nil {
901			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
902		}
903		rep.Shift = *sh
904	
905		for _, n := range d.Notes {
906			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
907				rep.OverlapNotes = append(rep.OverlapNotes, n)
908			}
909		}
910		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
911	
912		switch {
913		case !sh.Closed:
914			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
915			rep.Items = currentItemsOfShift(d, sh.ID)
916		case sh.CloseRecord != nil:
917			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
918			rep.ItemsAtClose = true
919			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
920			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
921			for _, s := range rep.CloseItems {
922				if it, _ := findItem(d, s.ItemID); it != nil {
923					rep.LatestItems[s.ItemID] = *it
924				}
925			}
926		default:
927			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
928			rep.HistoryIncomplete = true
929			rep.Items = currentItemsOfShift(d, sh.ID)
930		}
931		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
932	
933		for i := range d.Handovers {
934			h := &d.Handovers[i]
935			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
936			if !involved {
937				continue
938			}
939			if h.FromShiftID == sh.ID {
940				cp := *h
941				rep.Outgoing = &cp
942			}
943			if h.ToShiftID == sh.ID {
944				rep.Incoming = append(rep.Incoming, *h)
945			}
946			for j := range h.Entries {
947				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
948					HandoverID: h.ID,
949					FromShift:  h.FromShiftID,
950					ToShift:    h.ToShiftID,
951					Entry:      h.Entries[j],
952				})
953			}
954		}
955		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
956		for k := range rep.Results {
957			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
958		}
959		return rep, nil
960	}
